    for i in range(2, n + 1):
        fact *= i
    hashmap = {}
    for i in range(2, n + 1):
        k = (i * (i - 1)) // 2
        for j in range(2, i + 1):
            hashmap[j] = j * fact + k
    count = 0
    for i in range(n, 0, -1):
        index_map = defaultdict(int)
