import math

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def is_elegant(n):
    if n == 2:
        return True
    i = 2
    while i <= int(math.sqrt(n)) + 1:
        if n % i == 0:
            factors = prime_factors(i)
            gcd_val = factors[0]
            for factor in factors[1:]:
                gcd_val = gcd(gcd_val, factor)
            if gcd_val != 1:
                return False
            break
        i += 1
    return True

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def elegant_count(n):
    count = 0
    for i in range(2, n + 1):
        if is_elegant(i):
            count += 1
    return count

