    universes = 0
    n = len(planets)
    for i in range(n):
        visible = []
        for other_i in range(n):
            if i != other_i:
                dist = abs(planets[i][0] - planets[other_i][0]) + abs(planets[i][1] - planets[other_i][1])
                if dist == 0 or dist % 2 == 0:
                    visible.append([planets[i], planets[other_i]])
        if len(visible) > 0:
            universes += 1
    return universes

