# Function to get the destination city of the K-th traveler
def destination_city(N, M, K, travellers):
    grid = [[0]*M for _ in range(N)]
    marked = set()

    # Initialize destination set
    destination = set()
    for i in range(N):
        for j in range(M):
            if i * M + j != (K-1) * M:
                destination.add((i, j))
                continue
            curr_val = int(travellers[i][j])
            if curr_val == 0 and j+1 < M:
                destination.add((i, j + 1))
            elif curr_val == 1 and i+1 < N:
                destination.add((i + 1, j))
            grid[i][j] = 1 if curr_val == 0 else 0

    if destination:
        return min(destination)

    # If no initial position is marked
    initial_postion_count = sum(sum(grid[i][j]) for i in range(N) for j in range(M) if (i, j) not in marked)
    if initial_postion_count == 0:
        return (0, 0)

    # Check each position for balance
    dp = [[float('inf')]*M for _ in range(N)]
    dp[0][0] = 0
    for i in range(1, N):
        for j in range(M):
            dist, mark_mv = dist_marked_grid(grid, i, j, i-1, j, i, j, N, M, dp)
            dp[i][j] = min(dp[i-1][j] + dist, (M + i - j) // 2 + mark_mv)

    return min(pair[0] for pair in dp[-1])

# Check function to validate the solution with provided data points
def check(N, M, K, travellers, expected_routes):
    routes = destination_city(N, M, K, travellers)
    return routes == expected_routes

