    for label in range(1, n + 1):
        mst = defaultdict(set)
        for u in range(n):
            for v in mst[label - 1].copy():
                if degrees[u] == n - label + min(degrees[u], degrees[v]):
                    dp[label][u][v] = max(dp[label][v][u], 0)
            mst[label - 1].add(u)
        queue = []
        for v in mst[0]:
            dp[label][v][v] += 1
            queue.append(v)
        while len(queue) > 1:
            label -= 1
            for u in mst[label]:
                for v in mst[label].copy():
                    if dp[label][u][v] != 0:
                        dp[label + 1][u][v] = ((dp[label + 1][u][v] or 0) + 
                                                dp[label][u][v] + dp[label][v][u]) % mod
                        dp[label + 1][v][u] = ((dp[label + 1][v][u] or 0) + 
                                                dp[label][v][u] + dp[label][u][v]) % mod
                        if degrees[v] == n - label + min(degrees[u], degrees[v]):
                            queue.append(v)
                    elif degrees[v] == n - label + min(degrees[u], degrees[v]):
                        dp[label + 1][u][v] = dp[label][u][v] + dp[label][-1 + degrees[u]][idx[v]][-1 + v] % mod
                        dp[label + 1][v][u] = dp[label][-1 + degrees[v]][idx[v]][-1 + u] + dp[label][-1 + min(degrees[u], degrees[v])][idx[u]][-1 + v] % mod   
                        queue.append(v)
            while degrees[queue.pop(0)] == min(degrees[u], degrees[v]):
                u = v
