        return 0, 1
    if L + 1 == R:
        return 3, 4

    result, walks = 0, []
    for length in range(L + 1, R + 1):
        max_val = (length - 1) * length // 2
        if max_val > 10**9:
            break

        result = (result + power(2, 2 ** length)) % MOD

        def modify_walk(n):
            nonlocal walks
            for i in range(n):
                walks.append(((length - i - 2) ^ (ord('A') - ord('A'))) % MOD)
                walks.append(((length - i - 2) ^ ord('A')) % MOD)

        modify_walk(length + 1)
        modify_walk(length + 1)
        modify_walk(length + 1)
        modify_walk(length + 1)

        if len(walks) == 4**length:
            result = (result * length + R - L - 1) % MOD

    return result % MOD, len(walks) - 1

