def prime_factors(n):
    """Returns the prime factors of n in increasing order."""
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def count_elegant(upper_limit):
    """Counts the number of elegant numbers up to upper_limit."""
    count = 0
    for i in range(2, upper_limit + 1):
        f = prime_factors(i)
        if len(set(f)) == len(f):
            count += 1
    return count

