from heapq import heappop, heappush
from collections import defaultdict

def dijkstra(graph, start):
    """Compute shortest path from start to each vertex using Dijkstra's algorithm."""
    n = len(graph)
    distances = defaultdict(lambda: float('inf'))
    distances[start] = 0
    priority_queue = [(0, start)]  # (distance, vertex)

    while priority_queue:
        current_distance, current_vertex = heappop(priority_queue)

        if distances[current_vertex] < current_distance:
            continue

        for neighbor, weight in graph[current_vertex].items():
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))

    return distances

def set_priority_tree(start_priority, edges, graph):
    distinct_priorities = set(edge[0] + edge[1] for edge in edges)  # Find distinct priorities
    distinct_priorities.update(range(len(graph) + 1))  # Adjust 0-indexed priorities

    tree = defaultdict(lambda: defaultdict(int))
    for v, u in edges:
        tree[u][v] = start_priority

    # Assign leaf priorities
    for priority, distance in sorted(distinct_priorities):
        if distance == len(graph):
            # Leaves end up with max priority if distinct
            break
        for v in range(distance, weight + 1):
            tree[distance][v] = priority

    return tree

def process_queries(tree, queries):
