from collections import defaultdict

def is_decinc_subarray(p):
    stack = []
    for i, x in enumerate(p):
        if not stack or stack[-1] < x:
            stack.append(x)
        elif stack and stack[-1] < x:
            stack.pop()
    return len(stack) == 0

def count_decinc_pairs(n, p):
    p = sorted(p)
    if not is_decinc_subarray(p):
        return 0
    count = defaultdict(int)
    prev, current = 0, 0
    count[prev] += 1
    for i in range(n):
        if prev < i < current:
            count[i-1] += 1
        if i + 1 < n and p[i] < p[i+1]:
            curr = i
            current = max(current, max(curr, count[curr-1]))
            count[i] += 1
        if p[i] > p[i+1]:
            prev = curr
    return sum(count[v] * (current - v) for v in range(n))

