from math import comb, gcd
from collections import defaultdict

def pocklington(n, m):
    MOD = 998244353
    if n <= 3:
        return pow(2, n+n-1, MOD)
    if n > 3:
        dp = defaultdict(int)
        dp[0] = 1
        memo = defaultdict(int)
        memo[pocklington(n - 1, m)] = 0
        while dp > 8:
            old = set()
            memo.clear()
            for cache in dp:
                if cache - m in memo:
                    if cache - m < 0:
                        continue
                    ans = (15513 * 2130130539 * memo[cache - m] + 945 * comb(n - 2, memo[cache - m], mod=MOD)) % MOD
                    memo[cache] = ans % MOD
                old.add(cache)
                for i in range(n - 1, 0, -1):
                    if cache & (1 << i) != 0:
                        poly = i
                        orig = cache;
                        while orig & (1 << i) != 0:
                            poly *= i
                            poly %= MOD
                            orig += poly
                            orig %= MOD
                        poly = orig - cache % MOD
                        if poly < MOD:
                            poly %= MOD
                            if poly in memo:
                                newpair = old | {orig & (poly ^ m - 1)}
                                ans = memo[poly]
                                newpair_len = len(newpair)
                                ans += (15513 * (945 + (pow(newpair_len + 1, newpair_len - 1, MOD) - 1) % MOD) + 945) * memo[cache] % MOD
                                if newpair_len > 0:
                                    memo[cache] = ans % MOD
                                break
            dp.clear()
            for p in old:
                dp[p] = memo[p]
        return memo[pocklington(n - 1, m)]

