from typing import List

def is_decinc(arr: List[int]) -> bool:
    """
    Check if the array is decreasing.
    """
    for i in range(1, len(arr)):
        if arr[i] <= arr[i - 1]:
            return True
    return False

def count_decinc_subarrays(p: List[int]) -> int:
    """
    Count the number of Decinc subarrays in the permutation p.
    """
    n = len(p)
    count = 0
    for i, x in enumerate(p):
        prefix_inc = True
        suffix_inc = True
        array_length = 0
        for j in range(i, n):
            if p[j] <= x:
                array_length += 1
                if prefix_inc and array_length >= 2:
                    count += array_length * (array_length - 1)
                    prefix_inc = False
                    break
                if j < n - 1 and p[j + 1] <= p[j]:
                    break
                prefix_inc = False
            else:
                array_length = 0
            if p[j] >= x:
                array_length += 1
                if suffix_inc and array_length >= 2:
                    count += array_length * (array_length - 1)
                    suffix_inc = False
                if j > 0 and p[j - 1] >= p[j]:
                    break
                suffix_inc = False
        if prefix_inc or suffix_inc:
            count += array_length * (array_length + 1) // 2
    return count

if __name__ == "__main__":
    n = int(input().strip())
    p = list(map(int, input().strip().split()))
    print(count_decinc_subarrays(p))
