import functools
import math
from typing import List

def mex(arr):
    return lambda x: x if all(x not in arr) else mex(arr.union({x}))

def count_arrays(n: int, k: int, b: List[int]) -> int:
    MOD = 998244353
    pref = lambda pref, num: (num + pref - 1) % 998244353
    bf = mex({i for value in b for i in range(-k, k+1)})()

    @functools.lru_cache(None)
    def dp(k, reach) -> int:
        if k < 0:
            return 1
        if reach == 0:
            return 0
        res = pref(ret, mf(bf + (k-1, ))) % MOD
        for num in range(-reach, reach+1):
            if num <= -k or num >= k or (reach == k and num > 0):
                pt: int = bf(num)()
                res = (res - pref(ret - 1, pt) % MOD) % MOD
        return res

    return dp(k, n+1) % MOD

# Read input
n, k = map(int, input().split())
b = list(map(int, input().split()))

# Solve and print result
print(count_arrays(n, k, b))
