def split_planets(planets):
    # Create a dictionary to keep track of the count of planets in each column and row
    column_counts = defaultdict(int)
    row_counts = defaultdict(int)

    for x, y in planets:
        column_counts[x] += 1
        row_counts[y] += 1

    # If a planet is in a row or column with more than 1 planet, it cannot be split anymore
    cannot_split = {x for x, count in column_counts.items() if count > 2} | {
        y for y, count in row_counts.items() if count > 2
    }

    if (2 <= min(column_counts.values()) <= 3) or (2 <= min(row_counts.values()) <= 3):
        return 1  # Found a universe
    else:
        return 0  # Not found a universe

